16:   if (!hole.name.trim()) throw new Error(`Hole ${hole.id}: name must not be empty`);
17:   if (!Number.isInteger(hole.par) || hole.par < 1) {
18:     throw new Error(`Hole ${hole.id}: par must be a positive integer`);
19:   }
20:   if (!(hole.cup.radius > 0) || !(hole.cup.captureDepth > 0)) {
21:     throw new Error(`Hole ${hole.id}: cup dimensions must be positive`);
22:   }
