32:   for (const item of [...hole.surfaces, ...hole.obstacles]) {
33:     if (!item.id.trim()) throw new Error(`Hole ${hole.id}: element id must not be empty`);
34:     if (ids.has(item.id)) throw new Error(`Hole ${hole.id}: duplicate element id "${item.id}"`);
